tool_input.command:
cd "$(git rev-parse --show-toplevel)" && python - <<'EOF'
import re
p='src/styles/base.css'
s=open(p,encoding='utf-8').read()
start=s.index(':root {'); end=s.index('}',start)+1
new=''':root {
  /* Legacy names kept working as aliases of the Hardlift tokens (src/styles/tokens.css). */
  --color-bg: var(--color-surface-default);
  --color-surface: var(--color-surface-raised);
  --color-surface-muted: var(--color-surface-subtle);
  --color-sidebar-bg: var(--color-surface-default);
  --color-text: var(--color-text-primary);
  --color-text-muted: var(--color-text-secondary);
  --color-border: var(--color-border-default);
  --color-link: var(--color-text-secondary);
  --color-primary: var(--color-action-primary);
  --color-primary-text: var(--color-text-on-action);
  --color-focus: var(--color-focus-ring);
  --color-positive: var(--color-status-success);
  --color-negative: var(--color-status-danger);
  --color-danger-bg: var(--color-surface-subtle);
  --color-switch-off: var(--color-surface-raised);
  --color-switch-on: var(--color-action-inverse);
  --color-switch-thumb: var(--color-surface-raised);
  --color-strength-weak: var(--color-status-danger);
  --color-strength-fair: var(--color-status-warning);
  --color-strength-strong: var(--color-status-success);
  --color-pill-neutral-bg: var(--color-surface-raised);
  --color-pill-neutral-text: var(--color-text-primary);
  --color-pill-current-bg: var(--color-surface-raised);
  --color-pill-current-text: var(--color-text-primary);
  --color-pill-due-bg: var(--color-surface-raised);
  --color-pill-due-text: var(--color-text-primary);
  --color-backdrop: var(--color-scrim);

  --font-body: var(--font-family-body);
  --font-size-base: var(--font-size-md);
  --font-size-small: var(--font-size-sm);
  --font-size-h1: var(--font-size-3xl);
  --font-size-h2: var(--font-size-2xl);
  --line-height: var(--font-line-height-ui);

  --radius: var(--radius-sm);
  --radius-pill: var(--radius-full);
  --border-width: var(--border-width-thin);
  /* The old --space-1..8 names collide with the token scale (--space-4 = 4px), so they are retired. */
  --sidebar-width: 220px;
  --content-max-width: 880px;
  --avatar-size-large: 72px;
  --switch-width: 40px;
  --switch-height: 22px;
}'''
s=s[:start]+new+s[end:]
for old,newv in [('--space-1)','--space-4)'),('--space-2)','--space-8)'),('--space-3)','--space-12)'),('--space-6)','--space-24)')]:
    s=s.replace('var('+old,'var('+newv)
# --space-4 (16) and --space-8 (32) old usages: must map carefully; do in one pass with placeholders
open(p,'w',encoding='utf-8').write(s)
EOF
grep -n "var(--space" src/styles/base.css | head -50
